from lib import *
S = SS('w47')
steps = [
    step("快速重传:发送方收到足够多的重复 ACK,就认定中间那个包丢了,不等 RTO 就重传。netlab 给回环 20 ms 单向延迟(RTT 约 40 ms)和 1.5% 丢包,服务端向客户端发 2 MiB,用了 0.38 秒;tcp_info 里发送方发出 135 个包,重传 3 个(48996 字节)。抓包里被重传过的段正好 3 个,它们第一次重传距首次发送的间隔都是 42 ms——约等于一个 RTT 加上一点处理时间,而 RTO 至少是 200 多毫秒,所以这 3 次都是快速重传,没有一次是超时重传。", t=tl(S(1)), mark=lidx(S(1), '抓包里被重传过的段', '快速重传的间隔'), done=lidx(S(1), '传输 2 MiB'), b=bars([['发出的包', 135, '135'], ['重传的包', 3, '3'], ['重传间隔(中位)', 42, '42 ms'], ['RTT(2 × 20 ms)', 40, '40 ms']], 135, mark=[1, 2], done=[0, 3]), kv=KV([['2 MiB · 0.38 秒', '发出 135 个包,重传 3 个'], ['重传间隔', '42 ms ≈ 一个 RTT'], ['超时重传', '0 个']], ['重传间隔'])),
    step("重复 ACK 长什么样:对被快速重传的段,接收方在它重传之前回的 ACK 的确认号一直停在这个段的序号上——“我还在等这个字节”。第一个段(相对序号 1045248)抓到 5 条确认号停在它序号上的 ACK 记录,第二个(相对序号 1472064)抓到 16 条(同一个 ACK 在 dummynet 里会被抓到多份,所以条数大于实际个数),它们在首次发送后约 21 ms 就开始到达,重传发生在 +42 ms;第三个段(相对序号 1521060)一条这样的 ACK 都没有,但同样在 +42 ms 重传了——它离这次传输的结尾很近,后面没有足够的数据触发 3 个重复 ACK,可能是别的机制(如尾部丢失探测)触发的,这里没有进一步区分。机制:接收方每收到一个序号更大、但中间有洞的段,就立刻再发一次“我还在等第 X 个字节”的 ACK(不能等延迟 ACK);发送方数到 3 个这样的重复 ACK 就重传(RFC 5681)。", t=tl(S(2)), mark=lidx(S(2), '相对序号 1045248', '相对序号 1472064', '相对序号 1521060'), done=lidx(S(2), '说明'), kv=KV([['重复 ACK', '确认号停在丢失段的序号上'], ['触发', '数到 3 个重复 ACK'], ['第三个重传的段', '没有重复 ACK,靠别的机制'], ['说明', '为什么是 3:乱序 1~2 个包很常见']], ['触发'])),
    step("没有后续数据时就没有重复 ACK:只发一个包、等回显,netlab 30% 丢包。60 次单包收发里重传了 17 个不同的包(tcp_info 显示重传 24 次,有的包被重传了不止一次);首次重传的间隔最小 181、中位 189、最大 275 ms——是一个 RTT(40 ms)的 4~7 倍,量级是 RTO 或尾部探测的超时,而不是快速重传的 42 ms。原因:丢了的包后面没有别的数据能触发重复 ACK,只能等定时器。所以快速重传只对“窗口里有后续数据”的丢失有效;请求 / 应答式的小消息丢了只能靠定时器,重传的代价高得多。", t=tl(S(3)), mark=lidx(S(3), '60 次单包收发里'), done=lidx(S(3), '所以快速重传只对'), b=bars([['快速重传间隔(窗口里有后续数据)', 42, '42 ms'], ['单包丢失首次重传间隔(中位)', 189, '189 ms'], ['单包丢失首次重传间隔(最大)', 275, '275 ms']], 275, mark=[1, 2], done=[0]), kv=KV([['有后续数据', '重复 ACK 触发,42 ms 重传'], ['只发一个包', '没有重复 ACK,约 189 ms 才重传'], ['差距', '4~7 倍']], ['差距'])),
]
A = mkartw('w47', 47, '网络协议,TCP,快速重传,重复ACK,尾部丢失,真实验证,动画演示',
    '2 MiB 传输 1.5% 丢包里 3 次重传的间隔都是 42 ms(≈ 一个 RTT),是快速重传;单个小包丢了没有后续数据触发重复 ACK,首次重传要等 181~275 ms,是前者的 4~7 倍。',
    '为什么大文件传输里丢一两个包几乎没感觉,而小请求丢一个包就卡顿?这篇用抓包比较两种丢失:窗口里有后续数据时靠重复 ACK 快速重传,只有一个包时只能等定时器,时间差 4~7 倍。',
    [('42 ms', '大传输里丢包后快速重传距首次发送的间隔(RTT 40 ms),3 次重传全是快速重传'), ('189 ms', '只发一个小包丢了时的首次重传间隔中位数(最小 181、最大 275 ms)'), ('3 个重复 ACK', '触发快速重传所需的重复 ACK 个数(RFC 5681)')],
    [('重复 ACK', '<p>接收方遇到中间有洞的段,会立刻重发“我还在等第 X 个字节”的 ACK。数到 3 个就判定丢包,不等 RTO。</p>'),
     ('42 ms 对 189 ms', '<p>有后续数据时重传在约一个 RTT 之后发生;没有后续数据时要等定时器,慢 4~7 倍。</p>'),
     ('对设计的启示', '<p>请求 / 应答式的小消息对丢包最敏感,因为没有后续数据产生重复 ACK;所以小消息的延迟尾巴主要来自定时器。</p>')],
    steps,
    [ENV_W + '。全部在 lo0 上,丢包与延迟由 netlab 注入(单向 20 ms,RTT 约 40 ms);抓包里 dummynet 会让同一个包被抓到多份,按相隔 30 ms 去重分簇;第二节的“ACK 记录条数”包含这类重复,只用来说明确认号停在丢失段上,不是精确的重复 ACK 个数;重传次数很少(3 个),统计意义有限',
     '没有验证:SACK 如何把这类恢复做得更精确(见下一篇);尾部丢失探测(TLP)和 RACK 的具体触发条件;en0 真实网络上快速重传的比例;乱序造成的误快速重传(DSACK)'],
    '快速重传')
